21	/**
22	 * Parallel Coordinates
23	 * <https://en.wikipedia.org/wiki/Parallel_coordinates>
24	 */
25	
26	import * as zrUtil from 'zrender/src/core/util';
27	import * as matrix from 'zrender/src/core/matrix';
28	import * as layoutUtil from '../../util/layout';
29	import * as axisHelper from '../../coord/axisHelper';
30	import ParallelAxis from './ParallelAxis';
31	import * as graphic from '../../util/graphic';
32	import * as numberUtil from '../../util/number';
33	import sliderMove from '../../component/helper/sliderMove';
34	import ParallelModel, { ParallelLayoutDirection } from './ParallelModel';
35	import GlobalModel from '../../model/Global';
36	import ExtensionAPI from '../../core/ExtensionAPI';
37	import { Dictionary, DimensionName, ScaleDataValue } from '../../util/types';
38	import { CoordinateSystem, CoordinateSystemMaster } from '../CoordinateSystem';
39	import ParallelAxisModel, { ParallelActiveState } from './AxisModel';
40	import SeriesData from '../../data/SeriesData';
41	import { AxisBaseModel } from '../AxisBaseModel';
42	import { CategoryAxisBaseOption } from '../axisCommonTypes';
43	
44	const each = zrUtil.each;
45	const mathMin = Math.min;
46	const mathMax = Math.max;
47	const mathFloor = Math.floor;
48	const mathCeil = Math.ceil;
49	const round = numberUtil.round;
50	const PI = Math.PI;
51	
52	interface ParallelCoordinateSystemLayoutInfo {
53	    layout: ParallelLayoutDirection;
54	    pixelDimIndex: number;
55	    layoutBase: number;
56	    layoutLength: number;
57	    axisBase: number;
58	    axisLength: number;
59	    axisExpandable: boolean;
60	    axisExpandWidth: number;
61	    axisCollapseWidth: number;
62	    axisExpandWindow: number[];
63	    axisCount: number;
64	    winInnerIndices: number[];
65	    axisExpandWindow0Pos: number;
66	}
67	
68	export interface ParallelAxisLayoutInfo {
69	    position: number[];
70	    rotation: number;
71	    transform: matrix.MatrixArray;
72	    axisNameAvailableWidth: number;
73	    axisLabelShow: boolean;
74	    nameTruncateMaxWidth: number;
75	    tickDirection: -1 | 1;
76	    labelDirection: -1 | 1;
77	}
78	
79	type SlidedAxisExpandBehavior = 'none' | 'slide' | 'jump';
80	
81	class Parallel implements CoordinateSystemMaster, CoordinateSystem {
82	
83	    readonly type = 'parallel';
84	
85	    /**
86	     * key: dimension
87	     */
88	    private _axesMap = zrUtil.createHashMap<ParallelAxis>();
89	
90	    /**
91	     * key: dimension
92	     * value: {position: [], rotation, }
93	     */
94	    private _axesLayout: Dictionary<ParallelAxisLayoutInfo> = {};
95	
96	    /**
97	     * Always follow axis order.
98	     */
99	    readonly dimensions: ParallelModel['dimensions'];
100	
101	    private _rect: graphic.BoundingRect;
102	
103	    private _model: ParallelModel;
104	
105	    // Inject
106	    name: string;
107	    model: ParallelModel;
108	
109	
110	    constructor(parallelModel: ParallelModel, ecModel: GlobalModel, api: ExtensionAPI) {
111	        this.dimensions = parallelModel.dimensions;
112	        this._model = parallelModel;
113	
114	        this._init(parallelModel, ecModel, api);
115	    }
116	
117	    private _init(parallelModel: ParallelModel, ecModel: GlobalModel, api: ExtensionAPI): void {
118	
119	        const dimensions = parallelModel.dimensions;
120	        const parallelAxisIndex = parallelModel.parallelAxisIndex;
121	
122	        each(dimensions, function (dim, idx) {
123	
124	            const axisIndex = parallelAxisIndex[idx];
125	            const axisModel = ecModel.getComponent('parallelAxis', axisIndex) as ParallelAxisModel;
126	
127	            const axis = this._axesMap.set(dim, new ParallelAxis(
128	                dim,
129	                axisHelper.createScaleByModel(axisModel),
130	                [0, 0],
131	                axisModel.get('type'),
132	                axisIndex
133	            ));
134	
135	            const isCategory = axis.type === 'category';
136	            axis.onBand = isCategory
137	                && (axisModel as AxisBaseModel<CategoryAxisBaseOption>).get('boundaryGap');
138	            axis.inverse = axisModel.get('inverse');
139	
140	            // Injection
141	            axisModel.axis = axis;
142	            axis.model = axisModel;
143	            axis.coordinateSystem = axisModel.coordinateSystem = this;
144	
145	        }, this);
146	    }
147	
148	    /**
149	     * Update axis scale after data processed
150	     */
151	    update(ecModel: GlobalModel, api: ExtensionAPI): void {
152	        this._updateAxesFromSeries(this._model, ecModel);
153	    }
154	
155	    containPoint(point: number[]): boolean {
156	        const layoutInfo = this._makeLayoutInfo();
157	        const axisBase = layoutInfo.axisBase;
158	        const layoutBase = layoutInfo.layoutBase;
159	        const pixelDimIndex = layoutInfo.pixelDimIndex;
160	        const pAxis = point[1 - pixelDimIndex];
161	        const pLayout = point[pixelDimIndex];
162	
163	        return pAxis >= axisBase
164	            && pAxis <= axisBase + layoutInfo.axisLength
165	            && pLayout >= layoutBase
166	            && pLayout <= layoutBase + layoutInfo.layoutLength;
167	    }
168	
169	    getModel(): ParallelModel {
170	        return this._model;
171	    }
172	
173	    /**
174	     * Update properties from series
175	     */
176	    private _updateAxesFromSeries(parallelModel: ParallelModel, ecModel: GlobalModel): void {
177	        ecModel.eachSeries(function (seriesModel) {
178	
179	            if (!parallelModel.contains(seriesModel, ecModel)) {
180	                return;
181	            }
182	
183	            const data = seriesModel.getData();
184	
185	            each(this.dimensions, function (dim) {
186	                const axis = this._axesMap.get(dim);
187	                axis.scale.unionExtentFromData(data, data.mapDimension(dim));
188	                axisHelper.niceScaleExtent(axis.scale, axis.model);
189	            }, this);
190	        }, this);
191	    }
192	
193	    /**
194	     * Resize the parallel coordinate system.
195	     */
196	    resize(parallelModel: ParallelModel, api: ExtensionAPI): void {
197	        const refContainer = layoutUtil.createBoxLayoutReference(parallelModel, api).refContainer;
198	        this._rect = layoutUtil.getLayoutRect(parallelModel.getBoxLayoutParams(), refContainer);
199	
200	        this._layoutAxes();
201	    }
202	
203	    getRect(): graphic.BoundingRect {
204	        return this._rect;
205	    }
206	
207	    private _makeLayoutInfo(): ParallelCoordinateSystemLayoutInfo {
208	        const parallelModel = this._model;
209	        const rect = this._rect;
210	        const xy = ['x', 'y'] as const;
211	        const wh = ['width', 'height'] as const;
212	        const layout = parallelModel.get('layout');
213	        const pixelDimIndex = layout === 'horizontal' ? 0 : 1;
214	        const layoutLength = rect[wh[pixelDimIndex]];
215	        const layoutExtent = [0, layoutLength];
216	        const axisCount = this.dimensions.length;
217	
218	        const axisExpandWidth = restrict(parallelModel.get('axisExpandWidth'), layoutExtent);
219	        const axisExpandCount = restrict(parallelModel.get('axisExpandCount') || 0, [0, axisCount]);
220	        const axisExpandable = parallelModel.get('axisExpandable')
221	            && axisCount > 3
222	            && axisCount > axisExpandCount
223	            && axisExpandCount > 1
224	            && axisExpandWidth > 0
225	            && layoutLength > 0;
226	
227	        // `axisExpandWindow` is According to the coordinates of [0, axisExpandLength],
228	        // for sake of consider the case that axisCollapseWidth is 0 (when screen is narrow),
229	        // where collapsed axes should be overlapped.
230	        let axisExpandWindow = parallelModel.get('axisExpandWindow');
231	        let winSize;
232	        if (!axisExpandWindow) {
233	            winSize = restrict(axisExpandWidth * (axisExpandCount - 1), layoutExtent);
234	            const axisExpandCenter = parallelModel.get('axisExpandCenter') || mathFloor(axisCount / 2);
235	            axisExpandWindow = [axisExpandWidth * axisExpandCenter - winSize / 2];
236	            axisExpandWindow[1] = axisExpandWindow[0] + winSize;
237	        }
238	        else {
239	            winSize = restrict(axisExpandWindow[1] - axisExpandWindow[0], layoutExtent);
240	            axisExpandWindow[1] = axisExpandWindow[0] + winSize;
241	        }
242	
243	        let axisCollapseWidth = (layoutLength - winSize) / (axisCount - axisExpandCount);
244	        // Avoid axisCollapseWidth is too small.
245	        axisCollapseWidth < 3 && (axisCollapseWidth = 0);
246	
247	        // Find the first and last indices > ewin[0] and < ewin[1].
248	        const winInnerIndices = [
249	            mathFloor(round(axisExpandWindow[0] / axisExpandWidth, 1)) + 1,
250	            mathCeil(round(axisExpandWindow[1] / axisExpandWidth, 1)) - 1
251	        ];
252	
253	        // Pos in ec coordinates.
254	        const axisExpandWindow0Pos = axisCollapseWidth / axisExpandWidth * axisExpandWindow[0];
255	
256	        return {
257	            layout: layout,
258	            pixelDimIndex: pixelDimIndex,
259	            layoutBase: rect[xy[pixelDimIndex]],
260	            layoutLength: layoutLength,
261	            axisBase: rect[xy[1 - pixelDimIndex]],
262	            axisLength: rect[wh[1 - pixelDimIndex]],
263	            axisExpandable: axisExpandable,
264	            axisExpandWidth: axisExpandWidth,
265	            axisCollapseWidth: axisCollapseWidth,
266	            axisExpandWindow: axisExpandWindow,
267	            axisCount: axisCount,
268	            winInnerIndices: winInnerIndices,
269	            axisExpandWindow0Pos: axisExpandWindow0Pos
270	        };
271	    }
272	
273	    private _layoutAxes(): void {
274	        const rect = this._rect;
275	        const axes = this._axesMap;
276	        const dimensions = this.dimensions;
277	        const layoutInfo = this._makeLayoutInfo();
278	        const layout = layoutInfo.layout;
279	
280	        axes.each(function (axis) {
281	            const axisExtent = [0, layoutInfo.axisLength];
282	            const idx = axis.inverse ? 1 : 0;
283	            axis.setExtent(axisExtent[idx], axisExtent[1 - idx]);
284	        });
285	
286	        each(dimensions, function (dim, idx) {
287	            const posInfo = (layoutInfo.axisExpandable
288	                ? layoutAxisWithExpand : layoutAxisWithoutExpand
289	            )(idx, layoutInfo);
290	
291	            const positionTable = {
292	                horizontal: {
293	                    x: posInfo.position,
294	                    y: layoutInfo.axisLength
295	                },
296	                vertical: {
297	                    x: 0,
298	                    y: posInfo.position
299	                }
300	            };
301	            const rotationTable = {
302	                horizontal: PI / 2,
303	                vertical: 0
304	            };
305	
306	            const position = [
307	                positionTable[layout].x + rect.x,
308	                positionTable[layout].y + rect.y
309	            ];
310	
311	            const rotation = rotationTable[layout];
312	            const transform = matrix.create();
313	            matrix.rotate(transform, transform, rotation);
314	            matrix.translate(transform, transform, position);
315	
316	            // TODO
317	            // tick layout info
318	
319	            // TODO
320	            // update dimensions info based on axis order.
321	
322	            this._axesLayout[dim] = {
323	                position: position,
324	                rotation: rotation,
325	                transform: transform,
326	                axisNameAvailableWidth: posInfo.axisNameAvailableWidth,
327	                axisLabelShow: posInfo.axisLabelShow,
328	                nameTruncateMaxWidth: posInfo.nameTruncateMaxWidth,
329	                tickDirection: 1,
330	                labelDirection: 1
331	            };
332	        }, this);
333	    }
334	
335	    /**
336	     * Get axis by dim.
337	     */
338	    getAxis(dim: DimensionName): ParallelAxis {
339	        return this._axesMap.get(dim);
340	    }
341	
342	    /**
343	     * Convert a dim value of a single item of series data to Point.
344	     */
345	    dataToPoint(value: ScaleDataValue, dim: DimensionName): number[] {
346	        return this.axisCoordToPoint(
347	            this._axesMap.get(dim).dataToCoord(value),
348	            dim
349	        );
350	    }
351	
352	    /**
353	     * Travel data for one time, get activeState of each data item.
354	     * @param start the start dataIndex that travel from.
355	     * @param end the next dataIndex of the last dataIndex will be travel.
356	     */
357	    eachActiveState(
358	        data: SeriesData,
359	        callback: (activeState: ParallelActiveState, dataIndex: number) => void,
360	        start?: number,
361	        end?: number
362	    ): void {
363	        start == null && (start = 0);
364	        end == null && (end = data.count());
365	
366	        const axesMap = this._axesMap;
367	        const dimensions = this.dimensions;
368	        const dataDimensions = [] as DimensionName[];
369	        const axisModels = [] as ParallelAxisModel[];
370	
371	        zrUtil.each(dimensions, function (axisDim) {
372	            dataDimensions.push(data.mapDimension(axisDim));
373	            axisModels.push(axesMap.get(axisDim).model);
374	        });
375	
376	        const hasActiveSet = this.hasAxisBrushed();
377	
378	        for (let dataIndex = start; dataIndex < end; dataIndex++) {
379	            let activeState: ParallelActiveState;
380	
381	            if (!hasActiveSet) {
382	                activeState = 'normal';
383	            }
384	            else {
385	                activeState = 'active';
386	                const values = data.getValues(dataDimensions, dataIndex);
387	                for (let j = 0, lenj = dimensions.length; j < lenj; j++) {
388	                    const state = axisModels[j].getActiveState(values[j]);
389	
390	                    if (state === 'inactive') {
391	                        activeState = 'inactive';
392	                        break;
393	                    }
394	                }
395	            }
396	
397	            callback(activeState, dataIndex);
398	        }
399	    }
400	
401	    /**
402	     * Whether has any activeSet.
403	     */
404	    hasAxisBrushed(): boolean {
405	        const dimensions = this.dimensions;
406	        const axesMap = this._axesMap;
407	        let hasActiveSet = false;
408	
409	        for (let j = 0, lenj = dimensions.length; j < lenj; j++) {
410	            if (axesMap.get(dimensions[j]).model.getActiveState() !== 'normal') {
411	                hasActiveSet = true;
412	            }
413	        }
414	
415	        return hasActiveSet;
416	    }
417	
418	    /**
419	     * Convert coords of each axis to Point.
420	     *  Return point. For example: [10, 20]
421	     */
422	    axisCoordToPoint(coord: number, dim: DimensionName): number[] {
423	        const axisLayout = this._axesLayout[dim];
424	        return graphic.applyTransform([coord, 0], axisLayout.transform);
425	    }
426	
427	    /**
428	     * Get axis layout.
429	     */
430	    getAxisLayout(dim: DimensionName): ParallelAxisLayoutInfo {
431	        return zrUtil.clone(this._axesLayout[dim]);
432	    }
433	
434	    /**
435	     * @return {Object} {axisExpandWindow, delta, behavior: 'jump' | 'slide' | 'none'}.
436	     */
437	    getSlidedAxisExpandWindow(point: number[]): {
438	        axisExpandWindow: number[],
439	        behavior: SlidedAxisExpandBehavior
440	    } {
441	        const layoutInfo = this._makeLayoutInfo();
442	        const pixelDimIndex = layoutInfo.pixelDimIndex;
443	        let axisExpandWindow = layoutInfo.axisExpandWindow.slice();
444	        const winSize = axisExpandWindow[1] - axisExpandWindow[0];
445	        const extent = [0, layoutInfo.axisExpandWidth * (layoutInfo.axisCount - 1)];
446	
447	        // Out of the area of coordinate system.
448	        if (!this.containPoint(point)) {
449	            return {behavior: 'none', axisExpandWindow: axisExpandWindow};
450	        }
451	
452	        // Convert the point from global to expand coordinates.
453	        const pointCoord = point[pixelDimIndex] - layoutInfo.layoutBase - layoutInfo.axisExpandWindow0Pos;
454	
455	        // For dragging operation convenience, the window should not be
456	        // slided when mouse is the center area of the window.
457	        let delta;
458	        let behavior: SlidedAxisExpandBehavior = 'slide';
459	        const axisCollapseWidth = layoutInfo.axisCollapseWidth;
460	        const triggerArea = this._model.get('axisExpandSlideTriggerArea');
461	        // But consider touch device, jump is necessary.
462	        const useJump = triggerArea[0] != null;
463	
464	        if (axisCollapseWidth) {
465	            if (useJump && axisCollapseWidth && pointCoord < winSize * triggerArea[0]) {
466	                behavior = 'jump';
467	                delta = pointCoord - winSize * triggerArea[2];
468	            }
469	            else if (useJump && axisCollapseWidth && pointCoord > winSize * (1 - triggerArea[0])) {
470	                behavior = 'jump';
471	                delta = pointCoord - winSize * (1 - triggerArea[2]);
472	            }
473	            else {
474	                (delta = pointCoord - winSize * triggerArea[1]) >= 0
475	                    && (delta = pointCoord - winSize * (1 - triggerArea[1])) <= 0
476	                    && (delta = 0);
477	            }
478	            delta *= layoutInfo.axisExpandWidth / axisCollapseWidth;
479	            delta
480	                ? sliderMove(delta, axisExpandWindow, extent, 'all')
481	                // Avoid nonsense triger on mousemove.
482	                : (behavior = 'none');
483	        }
484	        // When screen is too narrow, make it visible and slidable, although it is hard to interact.
485	        else {
486	            const winSize2 = axisExpandWindow[1] - axisExpandWindow[0];
487	            const pos = extent[1] * pointCoord / winSize2;
488	            axisExpandWindow = [mathMax(0, pos - winSize2 / 2)];
489	            axisExpandWindow[1] = mathMin(extent[1], axisExpandWindow[0] + winSize2);
490	            axisExpandWindow[0] = axisExpandWindow[1] - winSize2;
491	        }
492	
493	        return {
494	            axisExpandWindow: axisExpandWindow,
495	            behavior: behavior
496	        };
497	    }
498	
499	    // TODO
500	    // convertToPixel
501	    // convertFromPixel
502	    // Note:
503	    // (1) Consider Parallel, the return type of `convertToPixel` could be number[][] (Point[]).
504	    // (2) In parallel coord sys, how to make `convertFromPixel` make sense?
505	    // Perhaps convert a point based on "a rensent most axis" is more meaningful rather than based on all axes?
506	}
507	
508	
509	function restrict(len: number, extent: number[]): number {
510	    return mathMin(mathMax(len, extent[0]), extent[1]);
511	}
512	
513	interface ParallelAxisLayoutPositionInfo {
514	    position: number;
515	    axisNameAvailableWidth: number;
516	    axisLabelShow: boolean;
517	    nameTruncateMaxWidth?: number;
518	}
519	
520	function layoutAxisWithoutExpand(
521	    axisIndex: number,
522	    layoutInfo: ParallelCoordinateSystemLayoutInfo
523	): ParallelAxisLayoutPositionInfo {
524	    const step = layoutInfo.layoutLength / (layoutInfo.axisCount - 1);
525	    return {
526	        position: step * axisIndex,
527	        axisNameAvailableWidth: step,
528	        axisLabelShow: true
529	    };
530	}
531	
532	function layoutAxisWithExpand(
533	    axisIndex: number,
534	    layoutInfo: ParallelCoordinateSystemLayoutInfo
535	): ParallelAxisLayoutPositionInfo {
536	    const layoutLength = layoutInfo.layoutLength;
537	    const axisExpandWidth = layoutInfo.axisExpandWidth;
538	    const axisCount = layoutInfo.axisCount;
539	    const axisCollapseWidth = layoutInfo.axisCollapseWidth;
540	    const winInnerIndices = layoutInfo.winInnerIndices;
541	
542	    let position;
543	    let axisNameAvailableWidth = axisCollapseWidth;
544	    let axisLabelShow = false;
545	    let nameTruncateMaxWidth;
546	
547	    if (axisIndex < winInnerIndices[0]) {
548	        position = axisIndex * axisCollapseWidth;
549	        nameTruncateMaxWidth = axisCollapseWidth;
550	    }
551	    else if (axisIndex <= winInnerIndices[1]) {
552	        position = layoutInfo.axisExpandWindow0Pos
553	            + axisIndex * axisExpandWidth - layoutInfo.axisExpandWindow[0];
554	        axisNameAvailableWidth = axisExpandWidth;
555	        axisLabelShow = true;
556	    }
557	    else {
558	        position = layoutLength - (axisCount - 1 - axisIndex) * axisCollapseWidth;
559	        nameTruncateMaxWidth = axisCollapseWidth;
560	    }
561	
562	    return {
563	        position: position,
564	        axisNameAvailableWidth: axisNameAvailableWidth,
565	        axisLabelShow: axisLabelShow,
566	        nameTruncateMaxWidth: nameTruncateMaxWidth
567	    };
568	}
569	
570	export default Parallel;
